    --accent-color: #3d5afe;
    --bg-color: #ffffff;
    --section-bg: #f9f9f9;
    --text-color: #333;
    --text-light: #777;
    --border-color: #eaeaea;
    --container-width: 1200px;
    --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --transition: all 0.3s ease;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-main);
    line-height: 1.6;
    color: var(--text-color);
    background-color: var(--bg-color);
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition);
}

ul {
    list-style: none;
}

img {
    max-width: 100%;
    display: block;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 2rem;
}

.btn {
    display: inline-block;
    padding: 0.8rem 1.5rem;
    border-radius: 4px;
    font-weight: 500;
    cursor: pointer;
    border: 1px solid transparent;
    transition: var(--transition);
    text-align: center;
}

.btn--primary {
    background-color: var(--primary-color);
    color: white;
}

.btn--primary:hover {
    background-color: #333;
}

.btn--outline {
    background-color: transparent;
    border-color: var(--primary-color);
    color: var(--primary-color);
}

.btn--outline:hover {
    background-color: var(--primary-color);
    color: white;
}

.btn--sm {
    padding: 0.5rem 1rem;
    font-size: 0.875rem;
}

.btn--link {
    padding: 0;
    color: var(--primary-color);
    font-weight: 600;
}

.btn--link:hover {
    color: var(--accent-color);
}

/* Header */
.header {
    padding: 1.5rem 0;
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(5px);
    z-index: 1000;
}

.header__container {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: -1px;
    color: var(--primary-color);
}

.nav__list {
    display: flex;
    gap: 2rem;
}

.nav__link {
    font-weight: 500;
    color: var(--secondary-color);
}

.nav__link:hover {
    color: var(--primary-color);
}

.header__actions {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.header__actions button {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--primary-color);
    display: flex;
    align-items: center;
    position: relative;
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -10px;
    background-color: var(--accent-color);
    color: white;
    font-size: 0.7rem;
    padding: 2px 6px;
    border-radius: 50%;
}

.menu-toggle {
    display: none;
}

/* Hero */
.hero {
    padding: 6rem 0;
    background-color: #f4f4f4;
    text-align: center;
}

.hero__content h1 {
    font-size: 3.5rem;
    margin-bottom: 1rem;
    line-height: 1.1;
}

.hero__content p {
    font-size: 1.25rem;
    color: var(--secondary-color);
    margin-bottom: 2rem;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

/* Sections */
.section {
    padding: 5rem 0;
}

.section__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 3rem;
}

.view-all {
    font-weight: 600;
    border-bottom: 2px solid var(--primary-color);
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    transition: var(--transition);
}

.product-card__image {
    aspect-ratio: 4/5;
    margin-bottom: 1rem;
    border-radius: 4px;
}

.product-card__info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.product-card__price {
    font-weight: 600;
    margin-bottom: 1rem;
}

/* Deals */
.deals-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
}

.deal-item {
    padding: 3rem;
    border-radius: 8px;
    display: flex;
    align-items: center;
}

.deal-item h3 {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.deal-item p {
    margin-bottom: 1.5rem;
    color: var(--secondary-color);
}

/* Editorial */
.editorial__grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.editorial__image {
    aspect-ratio: 1/1;
    border-radius: 8px;
}

.editorial__content h2 {
    font-size: 2.5rem;
    margin-bottom: 1.5rem;
}

.editorial__content p {
    font-size: 1.1rem;
    color: var(--secondary-color);
    margin-bottom: 2rem;
}

/* Footer */
.footer {
    background-color: var(--primary-color);
    color: white;
    padding: 4rem 0 2rem;
}

.footer__container {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: 3rem;
    margin-bottom: 4rem;
}

.footer__brand .logo {
    color: white;
    margin-bottom: 1rem;
    display: inline-block;
}

.footer__brand p {
    color: #999;
}

.footer__col h4 {
    margin-bottom: 1.5rem;
}

.footer__col ul li {
    margin-bottom: 0.75rem;
}

.footer__col ul li a {
    color: #999;
}

.footer__col ul li a:hover {
    color: white;
}

.footer__newsletter h4 {
    margin-bottom: 1.5rem;
}

.newsletter-form {
    display: flex;
    gap: 0.5rem;
}

.newsletter-form input {
    padding: 0.8rem;
    border: none;
    border-radius: 4px;
    flex: 1;
}

.footer__bottom {
    padding-top: 2rem;
    border-top: 1px solid #333;
    text-align: center;
    color: #666;
    font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 992px) {
    .footer__container {
        grid-template-columns: 1fr 1fr;
    }
    .editorial__grid {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
    .hero__content h1 {
        font-size: 2.5rem;
    }
}

@media (max-width: 768px) {
    .nav {
        display: none;
    }
    .menu-toggle {
        display: block;
    }
    .deals-grid {
        grid-template-columns: 1fr;
    }
    .hero {
        padding: 4rem 0;
    }
    .footer__container {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
}
