document.addEventListener('DOMContentLoaded', () => {
    // Cart Functionality
    const cartCountElement = document.querySelector('.cart-count');
    const addToCartButtons = document.querySelectorAll('.product-card .btn');
    let cartCount = 0;

    addToCartButtons.forEach(button => {
        button.addEventListener('click', () => {
            cartCount++;
            cartCountElement.textContent = cartCount;

            // Basic feedback
            const originalText = button.textContent;
            button.textContent = 'Added!';
            button.classList.add('btn--success');
            button.style.backgroundColor = '#4caf50';
            button.style.borderColor = '#4caf50';
            button.style.color = 'white';

            setTimeout(() => {
                button.textContent = originalText;
                button.style.backgroundColor = '';
                button.style.borderColor = '';
                button.style.color = '';
            }, 1500);
        });
    });

    // Newsletter Form
    const newsletterForm = document.querySelector('.newsletter-form');
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const email = newsletterForm.querySelector('input').value;
            if (email) {
                alert(`Thank you for subscribing with ${email}!`);
                newsletterForm.reset();
            }
        });
    }

    // Mobile Menu Toggle (Simplified)
    const menuToggle = document.querySelector('.menu-toggle');
    const navMenu = document.querySelector('.nav');

    if (menuToggle && navMenu) {
        menuToggle.addEventListener('click', () => {
            const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
            menuToggle.setAttribute('aria-expanded', !isExpanded);

            // For a real app, we'd toggle a class to show/hide the menu
            if (!isExpanded) {
                navMenu.style.display = 'block';
                navMenu.style.position = 'absolute';
                navMenu.style.top = '100%';
                navMenu.style.left = '0';
                navMenu.style.right = '0';
                navMenu.style.backgroundColor = 'white';
                navMenu.style.padding = '1rem 2rem';
                navMenu.style.borderBottom = '1px solid #eaeaea';

                const navList = navMenu.querySelector('.nav__list');
                navList.style.flexDirection = 'column';
                navList.style.gap = '1rem';
            } else {
                navMenu.style.display = 'none';
            }
        });
    }

    // Accessible Search button placeholder
    const searchBtn = document.querySelector('.search-btn');
    searchBtn.addEventListener('click', () => {
        const query = prompt('Search our collection:');
        if (query) {
            console.log(`Searching for: ${query}`);
        }
    });
});

